/**
 * Notion Node - Version 3
 * Discriminator: resource=block, operation=getAll
 */


interface Credentials {
  notionApi: CredentialReference;
  notionOAuth2Api: CredentialReference;
}

/** Get many child blocks */
export type NotionV3BlockGetAllParams = {
  resource: 'block';
  operation: 'getAll';
  authentication?: 'apiKey' | 'oAuth2' | Expression<string>;
/**
 * The Notion block to get children from
 * @default {"mode":"url","value":""}
 */
    blockId?: { __rl: true; mode: 'url' | 'id'; value: string; cachedResultName?: string };
/**
 * Whether to return all results or only up to a given limit
 * @default false
 */
    returnAll?: boolean | Expression<boolean>;
/**
 * Max number of results to return
 * @displayOptions.show { returnAll: [false] }
 * @default 50
 */
    limit?: number | Expression<number>;
/**
 * Fetch Nested Blocks
 * @default false
 */
    fetchNestedBlocks?: boolean | Expression<boolean>;
/**
 * Simplify Output
 * @default true
 */
    simplifyOutput?: boolean | Expression<boolean>;
};

export type NotionV3BlockGetAllOutput = {
  object?: string;
  id?: string;
  parent?: {
    type?: string;
    page_id?: string;
    block_id?: string;
  };
  last_edited_by?: {
    object?: string;
    id?: string;
  };
  has_children?: boolean;
  in_trash?: boolean;
  type?: string;
  content?: string;
  root_id?: string;
};

export type NotionV3BlockGetAllNode = {
  type: 'n8n-nodes-base.notion';
  version: 3;
  config: NodeConfig<NotionV3BlockGetAllParams> & { credentials?: Credentials };
  output?: Items<NotionV3BlockGetAllOutput>;
};